{
  "a_sentences": [
    {
      "a_text": "P1 Le litige porte sur la confirmation, par la Cour de justice, de la décision du 12 décembre 2024 sanctionnant l'Association pour non-respect des usages de la petite enfance sur plusieurs points.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2 La recourante fait valoir une violation de la primauté du droit fédéral (art. 49 Cst.) en soutenant qu'elle ne peut être sanctionnée pour ne pas avoir respecté les usages de la petite enfance, ceux-ci reprenant la CCT de la petite enfance de la Ville de Genève sans respecter la procédure d'extension prévue par la LECCT.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3 Selon un principe général de procédure, les conclusions constatatoires sont subsidiaires et ne sont recevables que lorsque des conclusions condamnatoires ou formatrices sont exclues.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4 Les conclusions constatatoires ne sont recevables que lorsque des conclusions condamnatoires ou formatrices sont exclues.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5 Les conclusions de l'Association tendant à constater l'illégalité des usages et directives sont irrecevables, dès lors que sa conclusion en annulation de l'arrêt attaqué est recevable et porte sur le refus de l'attestation et l'amende.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "P6 Ce procédé contourne les conditions et la procédure prévues par la LECCT, violant ainsi le principe de la primauté du droit fédéral (art. 49 Cst.).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "P7 En conséquence, la juridiction cantonale a confirmé à tort les mesures et l'amende infligées à l'Association en application de la LIRT/GE.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "P8 Le Tribunal fédéral admet le recours, annule l'arrêt attaqué et constate que les sanctions et mesures prises à l'encontre de l'Association n'ont pas lieu d'être.",
      "b_propositions": ["P8"]
    }
  ]
}
